<template>
  <div class="agenda-page">
    <Panel header="Agenda">
      <div v-if="agenda" class="agenda-header"><div><p class="agenda-date">{{ formatDate(agenda.date) }}</p><p class="agenda-description">Your reminders in {{ agenda.timeZone }}.</p></div><div class="agenda-current-time" aria-live="polite"><i class="pi pi-clock" aria-hidden="true"></i><span>Now {{ currentTime }}</span></div></div>
      <div v-if="agenda" class="agenda-summary" aria-label="Agenda summary"><span><i class="pi pi-check-circle" aria-hidden="true"></i>{{ completedCount }} completed</span><span><i class="pi pi-clock" aria-hidden="true"></i>{{ pendingCount }} pending</span><span><i class="pi pi-heart" aria-hidden="true"></i>{{ noIssueCount }} no back-pain issues</span></div>
      <p v-if="loading" class="agenda-empty">Loading agenda…</p><p v-else-if="agenda && !agenda.entries.length" class="agenda-empty">No push notifications are scheduled for today.</p>
      <ol v-else-if="agenda" class="agenda-timeline"><template v-for="(entry, index) in agenda.entries" :key="`${entry.type}-${entry.title}-${entry.scheduledTime}-${index}`"><li v-if="index === nowDividerIndex" ref="nowDivider" class="agenda-now" aria-label="Current time"><span></span><strong>Now</strong><span></span></li><li class="agenda-entry" :class="`agenda-entry-${entry.status.toLowerCase()}`"><time :datetime="entry.scheduledTime">{{ formatTime(entry.scheduledTime) }}</time><span class="agenda-entry-icon" aria-hidden="true"><i :class="entryIcon(entry.type)"></i></span><div class="agenda-entry-content"><strong>{{ entry.title }}</strong><span v-if="entry.details">{{ entry.details }}</span></div><span class="agenda-status" :class="`agenda-status-${entry.status.toLowerCase()}`"><i :class="statusIcon(entry.status)" aria-hidden="true"></i>{{ statusLabel(entry.status) }}</span><div class="agenda-actions"><Button v-if="entry.status === 'PENDING' && entry.type !== 'BACK_PAIN'" label="Complete" icon="pi pi-check" class="p-button-outlined" @click="complete(entry)" /><Button label="Change time" icon="pi pi-clock" class="p-button-text" @click="changeTime(entry)" /></div></li></template><li v-if="nowDividerIndex === agenda.entries.length" ref="nowDivider" class="agenda-now" aria-label="Current time"><span></span><strong>Now</strong><span></span></li></ol>
    </Panel>
    <MoodForm :initial_date="entryDate" :period="selectedEntry?.details?.toUpperCase()" fixed_date v-model:show="moodVisible" @onSave="saved" @onClose="closeForms" />
    <WeightForm :initial_date="entryDate" fixed_date v-model:show="weightVisible" @onSave="saved" @onClose="closeForms" />
    <BloodPressureForm :initial_date="entryDate" fixed_date v-model:show="bloodPressureVisible" @onSave="saved" @onClose="closeForms" />
    <Dialog appendTo="body" header="Complete routine" v-model:visible="routineVisible" :modal="true"><p>Mark <strong>{{ selectedEntry?.title }}</strong> as done?</p><template #footer><Button label="Mark as done" icon="pi pi-check" :loading="saving" @click="saveRoutine" /><Button label="Cancel" class="p-button-secondary" :disabled="saving" @click="routineVisible = false" /></template></Dialog>
    <Dialog appendTo="body" header="Take medication" v-model:visible="medicationVisible" :modal="true"><p>Mark <strong>{{ selectedEntry?.title }}</strong> as taken?</p><template #footer><Button label="Mark as taken" icon="pi pi-check" :loading="saving" @click="saveMedication" /><Button label="Cancel" class="p-button-secondary" :disabled="saving" @click="medicationVisible = false" /></template></Dialog>
    <Dialog appendTo="body" header="Change notification time" v-model:visible="timeVisible" :modal="true"><p>{{ timeDescription }}</p><label for="agenda-reminder-time">Time</label><Calendar inputId="agenda-reminder-time" v-model="selectedTime" :timeOnly="true" hourFormat="24" :stepMinute="5" :manualInput="false" showIcon /><template #footer><Button label="Save" icon="pi pi-check" :loading="saving" @click="saveTime" /><Button label="Cancel" class="p-button-secondary" :disabled="saving" @click="timeVisible = false" /></template></Dialog>
  </div>
</template>

<script>
import dayjs from 'dayjs';
import pushNotificationService from '../services/PushNotificationService';
import routineService from '../services/RoutineService';
import medicationService from '../services/MedicationService';
import MoodForm from './MoodForm.vue';
import WeightForm from './WeightForm.vue';
import BloodPressureForm from './BloodPressureForm.vue';
import {nextTick} from 'vue';

export default {components: {MoodForm, WeightForm, BloodPressureForm}, data() { return {agenda: null, loading: false, saving: false, currentDateTime: new Date(), clockInterval: null, selectedEntry: null, selectedTime: null, moodVisible: false, weightVisible: false, bloodPressureVisible: false, routineVisible: false, medicationVisible: false, timeVisible: false, scrolledToNow: false}; }, computed: {currentTime() { return !this.agenda ? '—' : new Intl.DateTimeFormat('en-GB', {timeZone: this.agenda.timeZone, hour: '2-digit', minute: '2-digit', hourCycle: 'h23'}).format(this.currentDateTime); }, nowDividerIndex() { const index = this.agenda.entries.findIndex(entry => this.formatTime(entry.scheduledTime) > this.currentTime); return index === -1 ? this.agenda.entries.length : index; }, completedCount() { return this.agenda.entries.filter(entry => ['COMPLETED', 'RECORDED'].includes(entry.status)).length; }, pendingCount() { return this.agenda.entries.filter(entry => ['PENDING', 'MISSED'].includes(entry.status)).length; }, noIssueCount() { return this.agenda.entries.filter(entry => entry.status === 'NO_ISSUE').length; }, entryDate() { return this.selectedEntry && new Date(`${this.agenda.date}T12:00:00`); }, timeDescription() { if (!this.selectedEntry) return ''; return ['MOOD', 'BACK_PAIN'].includes(this.selectedEntry.type) ? `This changes the ${this.selectedEntry.details.toLowerCase()} Mood and Back Pain reminders.` : `This changes future ${this.selectedEntry.title} notifications.`; }}, async created() { this.clockInterval = window.setInterval(() => { this.currentDateTime = new Date(); }, 60000); await this.loadAgenda(); }, beforeUnmount() { window.clearInterval(this.clockInterval); }, methods: {async loadAgenda() { this.loading = true; try { this.agenda = await pushNotificationService.getAgenda(); } catch (e) { this.$log.error(e); this.$toast.add({severity: 'error', summary: 'Agenda failed to load', detail: e, life: 3000}); } finally { this.loading = false; } if (!this.scrolledToNow) { await nextTick(); const nowDivider = Array.isArray(this.$refs.nowDivider) ? this.$refs.nowDivider[0] : this.$refs.nowDivider; nowDivider?.scrollIntoView({block: 'center'}); this.scrolledToNow = true; } }, formatDate(date) { return date ? dayjs(date).format('dddd, D MMMM') : 'today'; }, formatTime(time) { return time?.slice(0, 5) || '—'; }, entryIcon(type) { return {MOOD: 'pi pi-smile', BACK_PAIN: 'pi pi-heart', WEIGHT: 'pi pi-chart-line', BLOOD_PRESSURE: 'pi pi-heart-fill', ROUTINE: 'pi pi-check-square', MEDICATION: 'pi pi-plus-circle'}[type]; }, statusIcon(status) { return {COMPLETED: 'pi pi-check-circle', PENDING: 'pi pi-clock', MISSED: 'pi pi-times-circle', RECORDED: 'pi pi-info-circle', NO_ISSUE: 'pi pi-check-circle'}[status]; }, statusLabel(status) { return {COMPLETED: 'Completed', PENDING: 'Pending', MISSED: 'Missed', RECORDED: 'Recorded', NO_ISSUE: 'No issue'}[status]; }, complete(entry) { this.selectedEntry = entry; this.moodVisible = entry.type === 'MOOD'; this.weightVisible = entry.type === 'WEIGHT'; this.bloodPressureVisible = entry.type === 'BLOOD_PRESSURE'; this.routineVisible = entry.type === 'ROUTINE'; this.medicationVisible = entry.type === 'MEDICATION'; }, changeTime(entry) { this.selectedEntry = entry; this.selectedTime = this.toTime(entry.scheduledTime); this.timeVisible = true; }, toTime(value) { const [hours, minutes] = value.split(':').map(Number); const time = new Date(); time.setHours(hours, minutes, 0, 0); return time; }, serializedTime() { return `${String(this.selectedTime.getHours()).padStart(2, '0')}:${String(this.selectedTime.getMinutes()).padStart(2, '0')}`; }, async saved() { await this.loadAgenda(); this.closeForms(); }, closeForms() { this.moodVisible = false; this.weightVisible = false; this.bloodPressureVisible = false; this.selectedEntry = null; }, async saveRoutine() { await this.withSaving(async () => { await routineService.checkin(this.selectedEntry.routineId, this.entryDate); this.routineVisible = false; await this.loadAgenda(); }); }, async saveMedication() { await this.withSaving(async () => { await medicationService.logDose(this.selectedEntry.medicationId); this.medicationVisible = false; await this.loadAgenda(); }); }, async saveTime() { await this.withSaving(async () => { const time = this.serializedTime(); const entry = this.selectedEntry; if (entry.type === 'ROUTINE') await routineService.updateReminderTime(entry.routineId, entry.routineReminderId, time); else if (entry.type === 'MEDICATION') await medicationService.updateReminderTime(entry.medicationId, entry.scheduledTime.slice(0, 5), time); else { const settings = await pushNotificationService.getReminderSettings(); const key = {MOOD: entry.details.toLowerCase(), BACK_PAIN: entry.details.toLowerCase(), WEIGHT: 'weight', BLOOD_PRESSURE: 'bloodPressure'}[entry.type]; settings[`${key}Time`] = time; await pushNotificationService.saveReminderSettings(settings); } this.timeVisible = false; await this.loadAgenda(); this.$toast.add({severity: 'success', summary: 'Notification time saved', life: 3000}); }); }, async withSaving(action) { this.saving = true; try { await action(); } catch (e) { this.$log.error(e); this.$toast.add({severity: 'error', summary: 'Update failed', detail: e, life: 3000}); } finally { this.saving = false; } }} };
</script>

<style scoped>
.agenda-page{margin:1rem}.agenda-header{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem;margin-bottom:1rem}.agenda-date,.agenda-description{margin:0}.agenda-date{font-size:1.15rem;font-weight:600}.agenda-description,.agenda-entry-content span,.agenda-empty{color:#6c757d}.agenda-description{margin-top:.25rem}.agenda-current-time,.agenda-summary,.agenda-status,.agenda-actions{display:flex;align-items:center;gap:.4rem}.agenda-current-time{padding:.5rem .75rem;border-radius:4px;background:#eef5ff;color:#1f5d9e;font-weight:600}.agenda-summary,.agenda-actions{flex-wrap:wrap}.agenda-summary{gap:.75rem 1.25rem;margin-bottom:1.25rem;color:#495057;font-size:.9rem}.agenda-summary span{display:inline-flex;align-items:center;gap:.35rem}.agenda-timeline{margin:0;padding:0;list-style:none}.agenda-entry{display:grid;grid-template-columns:4.5rem 2.25rem minmax(0,1fr) auto auto;align-items:center;gap:.75rem;min-height:4.25rem;padding:.75rem 0;border-top:1px solid #e9ecef}.agenda-entry time{color:#495057;font-variant-numeric:tabular-nums;font-weight:600}.agenda-entry-icon{display:grid;width:2.25rem;height:2.25rem;place-items:center;border-radius:50%;background:#eef5ff;color:#1f5d9e}.agenda-entry-content{display:grid;gap:.2rem}.agenda-entry-content span,.agenda-status{font-size:.85rem}.agenda-status{justify-content:center;white-space:nowrap;font-weight:600}.agenda-status-completed,.agenda-status-no_issue{color:#2e7d32}.agenda-status-recorded{color:#1f5d9e}.agenda-status-pending{color:#8a5a00}.agenda-status-missed{color:#c62828}.agenda-entry-completed,.agenda-entry-no_issue{opacity:.68}.agenda-now{display:grid;grid-template-columns:1fr auto 1fr;gap:.75rem;align-items:center;margin:.75rem 0;padding:.45rem 0;color:#1f5d9e;font-size:.95rem}.agenda-now strong{padding:.2rem .55rem;border-radius:1rem;background:#e3f0ff}.agenda-now span{height:2px;background:#8bb8e8}@media(max-width:575px){.agenda-page{margin:.5rem}.agenda-header{align-items:stretch;flex-direction:column}.agenda-current-time{align-self:flex-start}.agenda-entry{grid-template-columns:3.75rem 2.25rem minmax(0,1fr);gap:.5rem}.agenda-status,.agenda-actions{grid-column:3;justify-content:flex-start}}
</style>
